require_once __DIR__.'/../includes/auth.php';requireLogin();$u=currentUser();$scope=$u['role']==='author'?' AND user_id='.(int)$u['id']:'';$stats=[];$stats['total']=(int)db()->query("SELECT COUNT(*) FROM news WHERE deleted_at IS NULL{$scope}")->fetchColumn();foreach(['published','draft','pending'] as $st){$stats[$st]=(int)db()->query("SELECT COUNT(*) FROM news WHERE deleted_at IS NULL AND status='{$st}'{$scope}")->fetchColumn();}$stats['deleted']=(int)db()->query("SELECT COUNT(*) FROM news WHERE deleted_at IS NOT NULL{$scope}")->fetchColumn();$stats['categories']=(int)db()->query('SELECT COUNT(*) FROM categories')->fetchColumn();$stats['users']=(int)db()->query('SELECT COUNT(*) FROM users')->fetchColumn();$stats['views']=(int)db()->query("SELECT COALESCE(SUM(views_count),0) FROM news WHERE deleted_at IS NULL{$scope}")->fetchColumn();$recent=db()->query("SELECT n.id,n.title,n.status,n.views_count,n.created_at,c.name category FROM news n LEFT JOIN categories c ON c.id=n.category_id WHERE n.deleted_at IS NULL".($u['role']==='author'?' AND n.user_id='.(int)$u['id']:'').' ORDER BY n.created_at DESC LIMIT 6')->fetchAll();$popular=db()->query("SELECT slug,title,views_count FROM news WHERE deleted_at IS NULL AND status='published' ORDER BY views_count DESC LIMIT 5")->fetchAll();$pageTitle='لوحة التحكم';require __DIR__.'/includes/header.php';$cards=[['total','كل الأخبار','bi-newspaper','primary'],['published','المنشورة','bi-check-circle','success'],['draft','المسودات','bi-file-earmark','secondary'],['pending','قيد المراجعة','bi-hourglass','warning'],['deleted','المحذوفة','bi-trash','danger'],['categories','التصنيفات','bi-tags','info'],['users','المستخدمون','bi-people','dark'],['views','إجمالي المشاهدات','bi-eye','primary']];?>
<div class="row g-3 mb-4"><?php foreach($cards as $c):if($c[0]==='users'&&!isAdmin())continue;?><div class="col-6 col-xl-3"><div class="card stat-card h-100"><div class="card-body d-flex align-items-center gap-3"><div class="stat-icon bg-<?=$c[3]?>-subtle text-<?=$c[3]?>"><i class="bi <?=$c[2]?>"></i></div><div><div class="text-secondary small"><?=$c[1]?></div><div class="fs-3 fw-bold"><?=number_format($stats[$c[0]])?></div></div></div></div></div><?php endforeach;?></div><div class="d-flex gap-2 mb-4"><a class="btn btn-primary" href="<?=url('admin/add-news.php')?>"><i class="bi bi-plus-lg"></i> خبر جديد</a><a class="btn btn-outline-primary" href="<?=url()?>">عرض الموقع</a></div><div class="row g-4"><div class="col-lg-8"><div class="card stat-card"><div class="card-header bg-white py-3 fw-bold">أحدث الأخبار</div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>العنوان</th><th>التصنيف</th><th>الحالة</th><th>التاريخ</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><a href="<?=url('admin/edit-news.php?id='.$r['id'])?>"><?=e($r['title'])?></a></td><td><?=e($r['category']??'—')?></td><td><span class="badge text-bg-<?=statusClass($r['status'])?>"><?=statusLabel($r['status'])?></span></td><td><?=formatDate($r['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-lg-4"><div class="card stat-card"><div class="card-header bg-white py-3 fw-bold">الأكثر مشاهدة</div><div class="list-group list-group-flush"><?php foreach($popular as $p):?><a class="list-group-item list-group-item-action d-flex justify-content-between" href="<?=url('news.php?slug='.rawurlencode($p['slug']))?>"><span><?=e($p['title'])?></span><span class="badge text-bg-light"><i class="bi bi-eye"></i> <?=$p['views_count']?></span></a><?php endforeach;?></div></div></div></div>
